(7248509, 1102156, 115814, '<td valign="top">I was the 9 vote on this image. Never got around to commenting, so...<br/> <br/>I really like the bold choices here. Not only the B&amp;W conversion, but the impenetrable shadows, the aggressive vignette, the grain, and the motion blur. I particularly like <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">posthumous</a>''s comment alluding to Picasso. Bravo!</td>', 'I was the 9 vote on this image. Never got around to commenting, so... I really like the bold choices here. Not only the B&W conversion, but the impenetrable shadows, the aggressive vignette, the grain, and the motion blur. I particularly like  posthumous''s comment alluding to Picasso. Bravo!', '2014-08-07 17:51:43.000000', NULL, 0),
(7250618, 1101988, 23484, '<td valign="top">This is absolutely gorgeous.</td>', 'This is absolutely gorgeous.', '2014-08-12 14:08:52.000000', NULL, 0);
